							<td class='contact' id="contact_<?php echo $contact_list[$i]->id;?>"><span id="profile_pic" style='margin-right:5px;'><?php if($contact_list[$i]->linkedin_image != ''){ ?><img src="<?php echo $contact_list[$i]->linkedin_image;?>" width="50"/> <?php }?></span> <a href='javascript://' onclick="window.parent.openContactEditForm(<?php echo $contact_list[$i]->id;?>)"><?php echo $contact_list[$i]->first_name." ".$contact_list[$i]->last_name;?> <span class="gender">(<?php echo $contact_list[$i]->gender==0?'M':'F';?>) <?php echo $class !=''?'<span class="'.$class.'"></span>':'';?></span></a><a href="javascript://" onclick="deleteUserFromCampaign(jQuery(this))" ><svg style="width:10px;position:relative;" aria-hidden="true" focusable="false" data-prefix="fas" data-icon="trash-alt" role="img" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 448 512" class="svg-inline--fa fa-trash-alt fa-w-14 fa-2x"><path fill="currentColor" d="M32 464a48 48 0 0 0 48 48h288a48 48 0 0 0 48-48V128H32zm272-256a16 16 0 0 1 32 0v224a16 16 0 0 1-32 0zm-96 0a16 16 0 0 1 32 0v224a16 16 0 0 1-32 0zm-96 0a16 16 0 0 1 32 0v224a16 16 0 0 1-32 0zM432 32H312l-9.4-18.7A24 24 0 0 0 281.1 0H166.8a23.72 23.72 0 0 0-21.4 13.3L136 32H16A16 16 0 0 0 0 48v32a16 16 0 0 0 16 16h416a16 16 0 0 0 16-16V48a16 16 0 0 0-16-16z" class=""></path></svg></a></td>
							<td class='job_title'><?php echo $contact_list[$i]->job_title;?></td>
							<td class='company' id="company_<?php echo $contact_list[$i]->company_id?>"><a href='javascript://' onclick="window.parent.openCompanyEdit(<?php echo $contact_list[$i]->company_id;?>)"><?php echo $companyName;?></a></td>						
							<td class='current_company'><?php echo $contact_list[$i]->current_company;?></td>
						</tr>
			<?php
					}
				}
			?>
			</tbody>
		</table>
	</div>
</div>
<div style='float:left;width:30%'> 
	<form action="" method="post" class="emaillinked-form">
		<button type="button" id='btnSendMessage' onclick="openActivity();" class="button" style='float:right;margin-bottom:10px;'>Call</button><button type="button" id='btnSendMessage' onclick="ignoreContact();" class="button" style='float:right;margin-bottom:10px;margin-right:10px;'>Skip the next invitee</button><button type="button" id='btnUpdateMessage' onclick="updateMessage(<?php echo $campaignID?>)" class="button" style='float:right;margin-bottom:10px;margin-right:10px;'>Save</button>
		<span style='float:right;'>Legend: use for firstname #First#, for lastname #Last#, for company #Company#, for saluation #Salutation#<br/></span> 
		<label>Body:</label><textarea name="body" id="body"><?php echo nl2br($body);?></textarea>	
	</form>
</div>	
<script>
	jQuery(document).ready(function(){
		fixHeaderWidth('main_list');
	});
	jQuery(window).resize(function(){
		fixHeaderWidth('main_list');
	});
	function callDone(contactID,companyID){
		let mainListTb = jQuery("#main_list").find('tbody tr[data-c="'+contactID+'"]');
		if(mainListTb.length > 0){
			let _campaign_id = mainListTb.attr('data-camp-id');
			let listID = mainListTb.attr('data-cam-id');
			mainListTb.remove();
			callRemaing();
			window.parent.call(window.parent.__baseUrl+'customers/update_campaign_skip','POST',{campaign_id:_campaign_id,id:listID,proccessed:0,send:1},window.parent.noActionPerform,'text');
		}		
	}
	function callRemaing(){
		jQuery("#send_counter_list").text(jQuery("#main_list").find('tbody tr').length);
	}
	function ignoreContact(){
		/*IGNORE EMAIL*/
		let mainListTb = jQuery("#main_list").find('tbody tr').eq(0);
		let _campaign_id = mainListTb.attr('data-camp-id');
		let listID = mainListTb.attr('data-cam-id');
		mainListTb.remove();
		callRemaing();
		/*Send Ajax Request For Ignore Email*/
		/*Send:2 IGNORE*/
		window.parent.call(window.parent.__baseUrl+'customers/update_campaign_skip','POST',{campaign_id:_campaign_id,id:listID,proccessed:1,send:2},window.parent.noActionPerform,'text');
	}
	function openActivity(){
		/**/
		let trList = jQuery("#main_list").find('tbody').find('tr');
		if(trList.length > 0){
			let trEle = trList.eq(0);
			let findContactID = trEle.attr('data-c');
			let findCompanyID = trEle.attr('data-co');
			console.log("openActivity",findContactID,findCompanyID);
			let findContainer;
			if(window.parent.jQuery("#activityTable").length > 0 && window.parent.jQuery("#activityTable").hasClass('show')){
				findContainer = window.parent.jQuery("#activityTable");
			}else if(window.parent.jQuery("#aquisitionTable").length > 0 && window.parent.jQuery("#aquisitionTable").hasClass('show')){
				findContainer = window.parent.jQuery("#aquisitionTable");
			}
			if(findContainer != undefined){
				if(findContainer.find("input[name='sales_person[]']:checked").length > 0){
					findContainer.find("input[name='sales_person[]']").prop("checked",false);
					window.parent.jQuery("#show_selected_count").text('');
				}
				let tbodyEle = findContainer.find('tbody.main_active');
				let trMaster = tbodyEle.find("tr.master[data-c='"+findCompanyID+"']");
				if(trMaster.length > 0){
					let trElement = trMaster.next();
					let ctrElement = trElement.find('tr.salesFDroppable[data-p="'+findContactID+'"]');
					if(ctrElement.length > 0){
						ctrElement.find('td').eq(0).find('a').trigger("click");
						//checkActivityDialogueOpen(findCompanyID,findContactID);
						setTimeout(()=>{checkActivityDialogueOpen(findCompanyID,findContactID)},300);
					}
				}
			}
		}		
	}
	function checkActivityDialogueOpen(findCompanyID,findContactID){
		let dialogueOpen = false;
		let checkDialogueBox = window.parent.jQuery("#callInOutModal");
		if(checkDialogueBox.length > 0){
			console.log("checkActivityDialogueOpen",1);
			if(checkDialogueBox.hasClass('is-open')){
				console.log("checkActivityDialogueOpen",2);
				dialogueOpen = true;
			}
		}
		if(dialogueOpen === true){
			let callCompanyID = checkDialogueBox.find("#callCompanyID").val();
			console.log("checkActivityDialogueOpen",callCompanyID);
			if(callCompanyID != "" && callCompanyID != undefined && callCompanyID != null){
				console.log("checkActivityDialogueOpen",callCompanyID,findCompanyID);
				if(parseInt(callCompanyID) == parseInt(findCompanyID)){
					let callContactID = checkDialogueBox.find("#callPerson").val();
					console.log("checkActivityDialogueOpen",callContactID,findCompanyID);
					if(callContactID != "" && callContactID != undefined && callContactID != null){
						console.log("checkActivityDialogueOpen",callContactID,findContactID);
						if(parseInt(callContactID) == parseInt(findContactID)){
							message = $("#body").code();
							console.log("checkActivityDialogueOpen",message);
							checkDialogueBox.find("#predefined_template").code(message);
						}
					}
				}
			}
		} else {
			setTimeout(()=>{checkActivityDialogueOpen(findCompanyID,findContactID)},300);
		}
	}
	function updateTemplateMessageOnFly(message){
		console.log("updateTemplateMessageOnFly:","I am in template message");
		$("#body").code(message);
		jQuery("#btnUpdateMessage").trigger("click");
	}
	function createElementOnFly(name,t){
		const createD = document.createElement('div');
		createD.style = "float:left;position:relative;left:-99999px;padding:0;margin:0px;font:400 18px/1.6em Roboto,sans-serif;";
		createD.innerHTML = name;
		createD.setAttribute('id','stton');
		const bTag = document.getElementsByTagName('body')[0];
		bTag.appendChild(createD);
		const tagD = document.getElementById('stton');
		let text =  t==1?tagD:tagD.innerText;
		if(t != 1){tagD.remove();}
		return text;
	}
	function updateMessage(cID){		
		console.log("updateMessage",jQuery("#body").code());
		let message = $("#body").code();
		plainText = createElementOnFly(message,1);
		if(cID > 0 && plainText!= "" && plainText != undefined){
			jQuery.ajax({
				url:'https://backyard.synpat.com/users/update_campaign_message',
				type:'POST',
				data:{campaign_id:cID,m:plainText}
			}).done(d => {
				console.log("CampaignMessage:",d)
			})
		}
	}
	function fixHeaderWidth(c){
		let tableEle = jQuery("#"+c);
		let tableHeadingEle = jQuery("#"+c+'_heading');
		
		let width = 0;
		tableHeadingEle.find('th').each(function(i){
			width = 0;
			var $thisH = $(this);;
			tableEle.find('tr').each(function(){
				var $this  = $(this);
				width = width > $this.find('td').eq(i).width() ? width : $this.find('td').eq(i).width();
			});
			$thisH.width(width);
		});
	}
	function deleteUserFromCampaign(o){
		let $tr = o.parents('tr');
		let campaignID = $tr.attr('data-camp-id');
		let campaignListID = $tr.attr('data-cam-id');
		if(campaignID > 0 && campaignListID > 0){
			jQuery.ajax({
				url:'https://backyard.synpat.com/users/delete_user_from_campaign',
				type:'POST',
				data:{campaign_id:campaignID,list_id:campaignListID}
			}).done(d => {
				if(d>0){
					$tr.remove();
				}
			})
		}
	}
	function updateDataInList(contactData){
		/*reff dashboard.js*/
		console.log("contactData",contactData);
		if(typeof contactData.id != "undefined"){
			let tblEle = jQuery("#main_list");
			let trEle = tblEle.find('tr[data-c="'+contactData.id+'"]');
			if(trEle.length > 0){
				trEle
					.attr('data-email',contactData.email)
					.attr('data-phone',contactData.phone)
					.attr('data-telephone',contactData.telephone)
					.attr('data-companyphone',contactData.companyphone)
					.attr('data-c',contactData.id)
					.attr('data-co',contactData.company_id)
					.attr('data-gender',contactData.gender)
					.attr('data-first_name',contactData.first_name)
					.attr('data-last_name',contactData.last_name)
				if(contactData.linkedin_image != '' && contactData.linkedin_image != null){
					trEle.find('td.contact').find("#profile_pic").html("<img src='"+contactData.linkedin_image+"' width='50'/>");
				}				
				_name = contactData.first_name+" "+contactData.last_name;
				if(contactData.gender==0){
					_name +="<span class='gender'>(M)</span>";
				} else {
					_name +="<span class='gender'>(F)</span>";
				}
				let companyName = contactData.company_name;
				if(contactData.company_name_alias != "" && contactData.company_name_alias != null){
					companyName = contactData.company_name_alias;
				}
				console.log("CANME",contactData.company_name_alias,companyName,contactData.company_name);
				trEle.find('td.contact').find('a').html(_name);
				trEle.find('td.company').find('a').html(companyName);
				trEle.find('td.current_company').html(contactData.current_company);
				trEle.find('td.job_title').html(contactData.job_title);
			}
		}
	}
</script>
